import React, { useEffect, useState } from "react";
import axios from "axios";
import "../styles/ChatSidebar.css";

const ChatSidebar = ({ setSelectedConversation }) => {
  const [conversations, setConversations] = useState([]);
  const user = JSON.parse(localStorage.getItem("user"));

  useEffect(() => {
    console.log("👤 Logged-in user from localStorage:", user);

    if (!user || !user.userId) return;

    const fetchConversations = async () => {
      try {
        const res = await axios.get(`http://localhost:5000/api/conversations/${user.userId}`);
        console.log("💬 Fetched conversations:", res.data);
        setConversations(res.data);
      } catch (err) {
        console.error("❌ Failed to fetch conversations:", err);
      }
    };

    fetchConversations();
  }, [user?.userId]);

  return (
    <div className="chat-sidebar">
      <h3>Messages</h3>
      {conversations.length === 0 ? (
        <p>No conversations found.</p>
      ) : (
        conversations.map((conv) => {
          const otherUsername = conv.participantUsernames.find(
            (name) => name !== user.username
          );

          return (
            <div
              key={conv._id}
              className="conversation-item"
              onClick={() => setSelectedConversation(conv)}
            >
              <strong>{otherUsername}</strong>
              <p className="last-message">{conv.lastMessage}</p>
            </div>
          );
        })
      )}
    </div>
  );
};

export default ChatSidebar;
